/// Look up a Hangul action id (case-sensitive, as in Hangul's own tables).
pub fn hwp_action(id: &str) -> Option<(&'static str, &'static str, &'static str)> {
    HWP_ACTIONS
        .binary_search_by(|(k, _, _, _)| k.cmp(&id))
        .ok()
        .map(|i| (HWP_ACTIONS[i].1, HWP_ACTIONS[i].2, HWP_ACTIONS[i].3))
}
